<?php
namespace ZinCelestial\Platform\Workflow;use RuntimeException;use ZinCelestial\Platform\Workflow\Contracts\WorkflowRepositoryInterface;defined('ABSPATH')||exit;
final class WorkflowEngine {public function __construct(private WorkflowRepositoryInterface $repo,private ActionRegistry $actions){}public function run(WorkflowDefinition $d,WorkflowRun $r,string $worker,int $version):WorkflowRun{if(!$this->repo->claim($r->id(),$worker,60))throw new RuntimeException('Workflow lease unavailable.');$completed=[];try{$r->start();foreach(array_slice($d->steps(),$r->cursor()) as $step){if(!$this->repo->heartbeat($r->id(),$worker,60))throw new RuntimeException('Workflow lease lost.');$h=$this->actions->get($step['action']);try{$result=$h->execute($r->context());$completed[]=[$h,$result];$r->advance();$version=$this->repo->save($r,$version);}catch(\Throwable $e){$r->fail('step_failed');foreach(array_reverse($completed) as [$done,$result]){try{$done->compensate($r->context(),$result);}catch(\Throwable $ignored){}}$this->repo->save($r,$version);return$r;}}$r->complete();$this->repo->save($r,$version);return$r;}finally{$this->repo->release($r->id(),$worker);}}}
